function(self, api, game, other) {
  // Both ghosts use this Script for their Step and Collision events.
  const powered = game.frame < (game.powerUntil || 0);
  if (other) {
    if (other.objectName !== 'pacman' || game.gameOver || self._eaten) return;
    if (powered) {
      self._eaten = true;
      self.visible = false;
      game.score = (Number(game.score) || 0) + 200;
      return;
    }
    if (game.frame < (game.ghostHitUntil || 0)) return;
    game.lives = (Number.isFinite(game.lives) ? game.lives : 3) - 1;
    game.ghostHitUntil = game.frame + 60;
    if (game.lives <= 0) {
      game.gameOver = true;
      game.paused = true;
      game.message = 'Game over';
      game.messageUntil = Number.MAX_SAFE_INTEGER;
      api.instance_destroy(other);
      api.instance_create(Math.round((game.viewX || 0) + ((game.viewWidth || game.width) - 276) / 2), Math.round((game.viewY || 0) + ((game.viewHeight || game.height) - 75) / 2), 'game_over');
      return;
    }
    other.x = other.startX;
    other.y = other.startY;
    other.hspeed = 0;
    other.vspeed = 0;
    other._gridNextMoveFrame = game.frame;
    other._gridLastMoveFrame = -1;
    other._gridLastDirection = null;
    game.message = 'Lives: ' + game.lives;
    game.messageUntil = game.frame + 120;
    return;
  }
  if (game.gameOver) return;
  if (self._eaten) {
    if (powered) return;
    self._eaten = false;
    self.visible = true;
    self.x = self.startX;
    self.y = self.startY;
    self.hspeed = 0;
    self.vspeed = 0;
    self._targetX = null;
    self._targetY = null;
    self._fromX = null;
    self._fromY = null;
    self._moveDirection = 'stop';
    self._nextChoice = null;
    self._wasPowered = false;
    return;
  }
  const tile = 34, speed = 2.5;
  const chasing = self.objectName === 'ghost2';
  const vectors = {right:[1,0], left:[-1,0], up:[0,-1], down:[0,1]};
  const pacman = api.instance_find('pacman');
  if (powered && !self._wasPowered && pacman && self._fromX != null && self._targetX != null) {
    const fromDistance = (self._fromX - pacman.x) ** 2 + (self._fromY - pacman.y) ** 2;
    const targetDistance = (self._targetX - pacman.x) ** 2 + (self._targetY - pacman.y) ** 2;
    if (fromDistance > targetDistance) {
      self._targetX = self._fromX;
      self._targetY = self._fromY;
      const reverse = {right:'left', left:'right', up:'down', down:'up'};
      self._moveDirection = reverse[self._moveDirection] || self._moveDirection;
    }
  }
  self._wasPowered = powered;
  let remaining = speed;
  while (remaining > 0) {
    // Finish each tile and carry any unused movement into the next tile.
    if (self._targetX == null || (self.x === self._targetX && self.y === self._targetY)) {
      self.x = Math.round(self.x / tile) * tile;
      self.y = Math.round(self.y / tile) * tile;
      const open = Object.keys(vectors).filter(direction => {
        const [dx, dy] = vectors[direction];
        const x = self.x + dx * tile, y = self.y + dy * tile;
        return x >= 0 && y >= 0 && x <= game.width - tile && y <= game.height - tile && !api.place_meeting(x, y, 'wall');
      });
      if (!open.length) break;
      let direction;
      if (powered || chasing) {
        if (!pacman) break;
        const reverse = {right:'left', left:'right', up:'down', down:'up'};
        const forward = powered ? open.filter(option => option !== reverse[self._moveDirection]) : open;
        const candidates = forward.length ? forward : open;
        direction = candidates.reduce((best, candidate) => {
          const [cx, cy] = vectors[candidate], [bx, by] = vectors[best];
          const candidateDistance = (self.x + cx * tile - pacman.x) ** 2 + (self.y + cy * tile - pacman.y) ** 2;
          const bestDistance = (self.x + bx * tile - pacman.x) ** 2 + (self.y + by * tile - pacman.y) ** 2;
          return (powered ? candidateDistance > bestDistance : candidateDistance < bestDistance) ? candidate : best;
        }, candidates[0]);
      } else {
        if (self._nextChoice == null || game.frame >= self._nextChoice) {
          const choices = Object.keys(vectors);
          self._preferredDirection = choices[Math.floor(Math.random() * choices.length)];
          self._nextChoice = game.frame + 180;
        }
        direction = open.includes(self._preferredDirection) ? self._preferredDirection
          : open.includes(self._moveDirection) ? self._moveDirection
          : open[Math.floor(Math.random() * open.length)];
      }
      const [dx, dy] = vectors[direction];
      self._moveDirection = direction;
      self._fromX = self.x;
      self._fromY = self.y;
      self._targetX = self.x + dx * tile;
      self._targetY = self.y + dy * tile;
    }
    const dx = self._targetX - self.x, dy = self._targetY - self.y;
    const step = Math.min(remaining, Math.abs(dx) + Math.abs(dy));
    if (!step) break;
    if (dx) self.x += Math.sign(dx) * step;
    else self.y += Math.sign(dy) * step;
    remaining -= step;
  }
}

function(self, api, game, other) {
  if (!other || other.objectName !== 'pacman' || game.gameOver) return;
  const powerPellet = self.objectName === 'power_pellet';
  game.score = (Number(game.score) || 0) + (powerPellet ? 100 : 10);
  if (powerPellet) {
    game.powerUntil = game.frame + 600;
    game.message = 'Power mode: eat the ghosts!';
    game.messageUntil = game.powerUntil;
  }
  api.instance_destroy(self);
  if (!api.instance_find('pellet') && !api.instance_find('power_pellet')) {
    game.gameOver = true;
    game.win = true;
    game.paused = true;
    game.message = 'All pellets eaten!';
    game.messageUntil = Number.MAX_SAFE_INTEGER;
    api.instance_create(Math.round((game.viewX || 0) + ((game.viewWidth || game.width) - 276) / 2), Math.round((game.viewY || 0) + ((game.viewHeight || game.height) - 75) / 2), 'you_win');
  }
}

function(self, api, game) {
  api.draw_self();
  if (self._eaten || game.frame >= (game.powerUntil || 0)) return;
  const color = '#6fdcff', size = 34, edge = 3;
  api.draw_rectangle(self.x, self.y, size, edge, color);
  api.draw_rectangle(self.x, self.y + size - edge, size, edge, color);
  api.draw_rectangle(self.x, self.y, edge, size, color);
  api.draw_rectangle(self.x + size - edge, self.y, edge, size, color);
}

function(self, api, game) {
  const viewX = Number(game.viewX) || 0;
  const viewY = Number(game.viewY) || 0;
  const viewWidth = Number(game.viewWidth) || Number(game.width) || 300;
  const viewHeight = Number(game.viewHeight) || Number(game.height) || 200;
  self.x = Math.round(viewX + (viewWidth - 276) / 2);
  self.y = Math.round(viewY + (viewHeight - 75) / 2);
  api.draw_self();
}
